import{_ as t,o as r,c as a,a3 as i}from"./chunks/framework.B9qR_F1m.js";const g=JSON.parse('{"title":"Datenschutz","description":"","frontmatter":{},"headers":[],"relativePath":"rechtliches/datenschutz.md","filePath":"rechtliches/datenschutz.md"}'),n={name:"rechtliches/datenschutz.md"};function s(d,e,h,u,l,o){return r(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="datenschutz" tabindex="-1">Datenschutz <a class="header-anchor" href="#datenschutz" aria-label="Permalink to &quot;Datenschutz&quot;">​</a></h1><p>Diese Erklärung gilt für das Handbuch unter handbuch.shardwing.de und die Startseite shardwing.de. Für die App selbst (app.shardwing.de und Desktop-App) steht eine eigene Erklärung in Shardwing unter <strong>Menü → Datenschutz</strong>.</p><h2 id="verantwortlich" tabindex="-1">Verantwortlich <a class="header-anchor" href="#verantwortlich" aria-label="Permalink to &quot;Verantwortlich&quot;">​</a></h2><p>Tom Niklas Achilles<br> Kirchenstraße 44<br> 22848 Norderstedt<br> E-Mail: <a href="mailto:kontakt@shardwing.de" target="_blank" rel="noreferrer">kontakt@shardwing.de</a></p><h2 id="kurz-gesagt" tabindex="-1">Kurz gesagt <a class="header-anchor" href="#kurz-gesagt" aria-label="Permalink to &quot;Kurz gesagt&quot;">​</a></h2><ul><li>Keine Cookies, kein Tracking, keine Werbung.</li><li>Schriften, Bilder und die Suche liegen alle auf dieser Seite selbst; es werden keine fremden Server angefragt.</li><li>Die Seite liegt bei GitHub. Dabei verarbeitet GitHub deine IP-Adresse.</li></ul><h2 id="hosting-bei-github-pages" tabindex="-1">Hosting bei GitHub Pages <a class="header-anchor" href="#hosting-bei-github-pages" aria-label="Permalink to &quot;Hosting bei GitHub Pages&quot;">​</a></h2><p>Das Handbuch wird von GitHub Pages ausgeliefert, einem Dienst der GitHub Inc., 88 Colin P. Kelly Jr. St, San Francisco, CA 94107, USA (Tochter von Microsoft). Beim Aufruf verarbeitet GitHub technisch nötige Daten wie IP-Adresse, Zeitpunkt und aufgerufene Seite, um die Seite auszuliefern und vor Angriffen zu schützen. Rechtsgrundlage ist Art. 6 Abs. 1 lit. f DSGVO; unser Interesse ist eine kostenlose, verlässliche Bereitstellung des Handbuchs. Microsoft ist nach dem EU-US Data Privacy Framework zertifiziert. Mehr dazu in der <a href="https://docs.github.com/de/site-policy/privacy-policies/github-general-privacy-statement" target="_blank" rel="noreferrer">Datenschutzerklärung von GitHub</a>.</p><h2 id="startseite-shardwing-de" tabindex="-1">Startseite shardwing.de <a class="header-anchor" href="#startseite-shardwing-de" aria-label="Permalink to &quot;Startseite shardwing.de&quot;">​</a></h2><p>Die Startseite liegt nicht bei GitHub, sondern auf einem eigenen Server in Deutschland, zusammen mit der App. Bei jedem Aufruf verarbeitet der Webserver technisch deine IP-Adresse, Zeitpunkt, aufgerufene Adresse und Browser-Kennung, um die Seite auszuliefern (Art. 6 Abs. 1 lit. f DSGVO). Zugriffsprotokolle werden nicht geschrieben. Die Startseite setzt keine Cookies und lädt nichts von fremden Servern.</p><p>Früher lief die App selbst unter shardwing.de. Öffnest du sie jetzt unter app.shardwing.de, holt sie einmalig über eine unsichtbare Hilfsseite der Startseite ab, was sie früher im Browser gespeichert hatte (Einstellungen, zuletzt geöffnete Missionen, Zugangs-Links), und löscht es dort. Das passiert nur in deinem Browser; der Server bekommt davon nichts mit.</p><h2 id="auf-deinem-gerat" tabindex="-1">Auf deinem Gerät <a class="header-anchor" href="#auf-deinem-gerat" aria-label="Permalink to &quot;Auf deinem Gerät&quot;">​</a></h2><p>Das Handbuch merkt sich im Browser (localStorage) nur, ob du den hellen oder dunklen Modus gewählt hast. Das ist für die Funktion nötig (§ 25 Abs. 2 Nr. 2 TDDDG) und verlässt dein Gerät nicht.</p><h2 id="downloads" tabindex="-1">Downloads <a class="header-anchor" href="#downloads" aria-label="Permalink to &quot;Downloads&quot;">​</a></h2><p>Die Download-Links führen zu den Releases auf GitHub. Dort gelten die Datenschutzbestimmungen von GitHub.</p><h2 id="e-mail" tabindex="-1">E-Mail <a class="header-anchor" href="#e-mail" aria-label="Permalink to &quot;E-Mail&quot;">​</a></h2><p>Schreibst du an <a href="mailto:kontakt@shardwing.de" target="_blank" rel="noreferrer">kontakt@shardwing.de</a>, nimmt Cloudflare Inc. (USA) die Mail an und leitet sie an das Postfach des Betreibers weiter (Cloudflare Email Routing). Cloudflare speichert dabei keine Inhalte, verarbeitet aber Absender, Empfänger und Zeitpunkt; es ist nach dem EU-US Data Privacy Framework zertifiziert. Rechtsgrundlage ist Art. 6 Abs. 1 lit. f DSGVO – wir möchten deine Nachricht beantworten können.</p><h2 id="deine-rechte" tabindex="-1">Deine Rechte <a class="header-anchor" href="#deine-rechte" aria-label="Permalink to &quot;Deine Rechte&quot;">​</a></h2><p>Du hast das Recht auf Auskunft, Berichtigung, Löschung, Einschränkung der Verarbeitung, Datenübertragbarkeit und Widerspruch (Art. 15–21 DSGVO). Schreib dafür an <a href="mailto:kontakt@shardwing.de" target="_blank" rel="noreferrer">kontakt@shardwing.de</a>. Beschweren kannst du dich bei einer Datenschutz-Aufsichtsbehörde, etwa der deines Bundeslandes oder der für den Betreiber zuständigen (<a href="https://www.datenschutzzentrum.de" target="_blank" rel="noreferrer">Unabhängiges Landeszentrum für Datenschutz Schleswig-Holstein, ULD</a>).</p>',19)])])}const b=t(n,[["render",s]]);export{g as __pageData,b as default};
